import { Skeleton, Row, Col, Switch, Divider, Button, Slider } from 'antd';

import { EnvironmentType, useHypercubeContext } from '../../../HypercubeContext';

import styles from './PanelSandbox.module.css';

const PanelSandbox = () => {
	const { environmentType, shiftEnvironmentType, restartApp, selectedFOV, shiftFOV, moveForwardFn, moveBackwardFn, animationA, animationB } = useHypercubeContext();

	const title = 'Hypercube Sandbox';
	const size = 'default';
	const value = [1, 2, 3];

	const cardStyle = `card${size}`;
	const colSize = size === 'default' ? '100%' : size === 'small' ? '48.375%' : '130px';
	const nestedValue = Array.isArray(value) ? value : [value];

	return (
		<div>
			<Row gutter={[8, 8]} className={'styles.contentContainer'}>
				<Col
					flex={colSize}
					className={styles[cardStyle]}
					style={{
						paddingRight: 12,
						paddingLeft: 12,
						paddingTop: 12,
						paddingBottom: 12,
					}}
				>
					<Col flex="auto">
						{title && (
							<Row style={{ width: '100%' }} className={styles.titleH1}>
								<span>{title}</span>
							</Row>
						)}
						<Button onClick={restartApp}> reset</Button>
						<Divider className={styles.titleSub} style={{ borderColor: '#fff', color: '#fff' }}>
							Scene env
						</Divider>
						{Object.values(EnvironmentType).map((env) => (
							<Row key={env} className={styles.sceneList}>
								<Switch size="small" checked={environmentType === env} onClick={() => shiftEnvironmentType(env)} />
								<span>{env}</span>
							</Row>
						))}
						<Divider className={styles.titleSub} style={{ borderColor: '#fff', color: '#fff' }}>
							Camera
						</Divider>

						<Row style={{ width: '100%' }}>
							<Button className={styles.uiBtnViewChanging} onClick={moveBackwardFn}>
								{`<`}
							</Button>
							<Button className={styles.uiBtnViewChanging} onClick={moveForwardFn}>
								{'>'}
							</Button>
						</Row>

						<Row style={{ width: '100%' }}>
							<Slider className={styles.uiSlider} defaultValue={30} min={15} max={60} onChange={shiftFOV} value={typeof selectedFOV === 'number' ? selectedFOV : 0} />
							<p>FOV</p>
						</Row>

						<Row style={{ width: '100%' }}>
							<Switch size="small" onChange={animationA}></Switch> <span>{' Animation A'}</span>
						</Row>
						<Row style={{ width: '100%' }}>
							<Switch size="small" onChange={animationB}></Switch> <span>{` Animation B`}</span>
						</Row>
					</Col>
				</Col>
			</Row>
		</div>
	);
};
export default PanelSandbox;
