import React, { createContext, useContext, useState, ReactNode } from 'react';

import { EnvironmentType } from './utils/ReactHypercube';

type HypercubeContextType = {
	restart: number;
	setRestart: (val: number) => void;
	restartApp: () => void;

	selectedFOV: number;
	setSelectedFOV: (val: number) => void;
	shiftFOV: (val: number) => void;

	environmentType: EnvironmentType;
	setEnvironmentType: (envType: EnvironmentType) => void;
	shiftEnvironmentType: (envType: EnvironmentType) => void;

	moveForwardFn: () => void;
	setMoveForwardFn: React.Dispatch<React.SetStateAction<() => void>>;

	moveBackwardFn: () => void;
	setMoveBackwardFn: React.Dispatch<React.SetStateAction<() => void>>;

	animationA: () => void;
	setAnimationA: React.Dispatch<React.SetStateAction<() => void>>;

	animationB: () => void;
	setAnimationB: React.Dispatch<React.SetStateAction<() => void>>;
};

const HypercubeContext = createContext<HypercubeContextType | undefined>(undefined);

export { EnvironmentType };

export const HypercubeProvider = ({ children }: { children: ReactNode }) => {
	const [restart, setRestart] = useState(0);
	const restartApp = () => {
		setRestart(Math.random() * 100);
	};

	const [selectedFOV, setSelectedFOV] = useState(30);
	const shiftFOV = (v: number) => {
		setSelectedFOV(v);
	};

	const [environmentType, setEnvironmentType] = useState<EnvironmentType>(EnvironmentType.Studio);
	const shiftEnvironmentType = (env: EnvironmentType) => {
		setEnvironmentType((prev) => (prev === env ? null : env));
	};

	const [moveForwardFn, setMoveForwardFn] = useState<() => void>(() => () => {});
	const [moveBackwardFn, setMoveBackwardFn] = useState<() => void>(() => () => {});

	const [animationA, setAnimationA] = useState<() => void>(() => () => {});
	const [animationB, setAnimationB] = useState<() => void>(() => () => {});

	// const moveCameraForward

	return (
		<HypercubeContext.Provider
			value={{
				restart,
				setRestart,
				restartApp,

				selectedFOV,
				setSelectedFOV,
				shiftFOV,

				environmentType,
				setEnvironmentType,
				shiftEnvironmentType,

				// .................. function binding
				moveForwardFn,
				setMoveForwardFn,

				moveBackwardFn,
				setMoveBackwardFn,

				animationA,
				setAnimationA,
				animationB,
				setAnimationB,
			}}
		>
			{children}
		</HypercubeContext.Provider>
	);
};

export const useHypercubeContext = () => {
	const context = useContext(HypercubeContext);
	if (!context) {
		throw new Error('useHypercubeContext must be used within a MyProvider');
	}
	return context;
};
