import { useState } from 'react';

import { DownOutlined } from '@ant-design/icons';

import { Button } from 'antd';
import { motion } from 'framer-motion';

import PanelSandbox from './HypercubePanels/PanelSandbox';

import styles from './ControlPanel.module.css';

export const LEFT_CONTROL_PANEL_ANIMATION_CONFIG = {
	open: {
		transition: {
			type: 'spring',
			bounce: 0,
			duration: 0.6,
		},
		x: 0,
	},
	closed: {
		transition: {
			type: 'spring',
			bounce: 0,
			duration: 0.6,
		},
		x: '-200px',
	},
};

const ControlPanel = ({}) => {
	let controlPaneOpen = true;
	const [controlPaneIsOpen, setControlPaneIsOpen] = useState(controlPaneOpen);
	const togglePanel = () => {
		setControlPaneIsOpen(!controlPaneIsOpen);
	};

	const panelBody = 'sandbox';

	const renderControlPanel = () => {
		switch (panelBody) {
			case 'sandbox':
				return <PanelSandbox />;
			// case 'beadProgress':
			// 	return <BeadProgressPanel />;
			// default:
			// 	return <DefaultControlPanel />;
		}
	};

	return (
		<motion.div animate={controlPaneIsOpen ? 'open' : 'closed'} variants={LEFT_CONTROL_PANEL_ANIMATION_CONFIG} className={`${styles.draggableContainer}`}>
			<Button
				className={controlPaneIsOpen ? styles.layersButtonExpanded : styles.layersButton}
				icon={<DownOutlined className={controlPaneIsOpen ? styles.layersButtonIconOpen : styles.layersButtonIconClose} />}
				onClick={togglePanel}
			/>
			<motion.div className={styles.container}>{renderControlPanel()}</motion.div>
		</motion.div>
	);
};
export default ControlPanel;
