import { useState } from 'react';

import ControlPanel from './ControlPanel';
import HypercubeWrapper from './HypercubeWrapper';

import style from './styles.module.css';

type Props = {
	id: string;
};

const Hypercube = ({ id }: Props) => {
	const [open, setOpen] = useState(false);

	const showDrawer = () => {
		setOpen(true);
	};

	const onClose = () => {
		setOpen(false);
	};

	return (
		<>
			<div className={`sliding-panel-wrapper ${open ? 'open' : ''}`}>
				<ControlPanel />
			</div>

			<div className={style.hypercubeDivWrapper}>
				<HypercubeWrapper id={id} />
			</div>
		</>
	);
};

export default Hypercube;
